 12	public final class KmpPattern {
 13	    private final String value;
 14	    private final int[] longestPrefixSuffix;
 15	
 16	    private KmpPattern(String value, int[] longestPrefixSuffix) {
 17	        this.value = value;
 18	        this.longestPrefixSuffix = longestPrefixSuffix;
 19	    }
 20	
 21	    public static KmpPattern compile(CharSequence pattern) {
 22	        Objects.requireNonNull(pattern, "pattern must not be null");
 23	
 24	        String patternValue = pattern.toString();
 25	        if (patternValue.isEmpty()) {
 26	            throw new IllegalArgumentException("pattern must not be empty");
 27	        }
 28	
 29	        return new KmpPattern(patternValue, buildLongestPrefixSuffixTable(patternValue));
 30	    }
 31	
 32	    public String value() {
 33	        return value;
 34	    }
 35	
 36	    public KmpMatchIterator matchIteratorIn(CharSequence text) {
 37	        validateText(text);
 38	        return new KmpMatchIterator(value, longestPrefixSuffix, text);
 39	    }
 40	
 41	    public KmpMatchResult analyzeIn(CharSequence text) {
 42	        List<Integer> matches = new ArrayList<>();
 43	        KmpMatchIterator iterator = matchIteratorIn(text);
 44	        iterator.forEachRemaining((int matchIndex) -> matches.add(matchIndex));
 45	
 46	        if (matches.isEmpty()) {
 47	            return KmpMatchResult.noMatches();
 48	        }
 49	
 50	        return KmpMatchResult.from(matches);
 51	    }
