 63	        int matchCount = 0;
 64	        KmpMatchIterator iterator = matchIteratorIn(text);
 65	
 66	        while (iterator.hasNext()) {
 67	            iterator.nextInt();
 68	            matchCount++;
 69	        }
 70	
 71	        return matchCount;
 72	    }
