 83	    static int[] buildLongestPrefixSuffixTable(String pattern) {
 84	        int[] table = new int[pattern.length()];
 85	        int prefixLength = 0;
 86	        int currentIndex = 1;
 87	
 88	        while (currentIndex < pattern.length()) {
 89	            if (pattern.charAt(currentIndex) == pattern.charAt(prefixLength)) {
 90	                table[currentIndex] = ++prefixLength;
